 // This is the listener class for the send operation. We have to create this
 // class to listen for message send completion and eventually notify the caller
 ////////////////////////////////////////////////////////////////////////////////////
-class nsMsgComposeSendListener : public nsIMsgComposeSendListener,
-                                 public nsIMsgSendListener,
+class nsMsgComposeSendListener : public nsIMsgSendListener,
                                  public nsIMsgCopyServiceListener,
                                  public nsIWebProgressListener,
                                  public nsSupportsWeakReference {
  public:
-  nsMsgComposeSendListener(void);
+  nsMsgComposeSendListener(nsIMsgCompose* compose, MSG_DeliverMode deliverMode);

   // nsISupports interface
   NS_DECL_ISUPPORTS

-  // nsIMsgComposeSendListener interface
-  NS_DECL_NSIMSGCOMPOSESENDLISTENER
-
   // nsIMsgSendListener interface
   NS_DECL_NSIMSGSENDLISTENER

@@ -223,7 +219,20 @@ class nsMsgComposeSendListener : public nsIMsgComposeSendListener,

  private:
   virtual ~nsMsgComposeSendListener();
+
+  // The working handle to the compose object. Weak, because the send and
+  // copy operations keep this listener alive, and the compose object keeps
+  // those operations alive; a strong handle would turn that into a permanent
+  // reference loop.
   nsWeakPtr mWeakComposeObj;
+  // Only here to keep the compose object alive while a send is in flight,
+  // never used as a handle. MessageSend resolves its send promise before the
+  // deferred final OnStopCopy() callback, so JS may otherwise drop the
+  // compose object before we are done with it. The terminal send, copy, and
+  // progress callbacks drop this reference; if a deferred OnStopCopy() still
+  // arrives after that (e.g. after a canceled copy), the weak reference
+  // covers it as long as the compose window is open.
+  nsCOMPtr<nsIMsgCompose> mComposeKeepAlive;
   MSG_DeliverMode mDeliverMode;
 };

diff --git a/mailnews/compose/test/unit/test_nsMsgComposeSendListener.js b/mailnews/compose/test/unit/test_nsMsgComposeSendListener.js
new file mode 100644
index 00000000000..726e5a6ff25
--- /dev/null
+++ b/mailnews/compose/test/unit/test_nsMsgComposeSendListener.js
@@ -0,0 +1,134 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this file,
+ * You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+/*
+ * Tests nsMsgComposeSendListener, as a regression test for bug 2050589:
+ * onStopCopy() must close the progress dialog even if GC dropped the JS
+ * references to the compose object. Intentionally incomplete.
+ *
+ * TODO: Add more nsMsgComposeSendListener test coverage here.
+ */
+
+add_setup(function () {
+  localAccountUtils.loadLocalMailAccount();
+});
+
+add_task(async function testOnStopCopyClosesProgressAfterGC() {
+  const fakeSend = {
+    listener: null,
+
+    observe(subject) {
+      // "mail-set-sender" fires right before sendMsg() creates the real
+      // MessageSend, so the fake takes its place here.
+      const compose = subject.QueryInterface(Ci.nsIMsgCompose);
+      compose.messageSend = this.QueryInterface(Ci.nsIMsgSend);
+    },
+
+    createAndSendMessage(
+      _editor,
+      _identity,
+      _accountKey,
+      _fields,
+      _isDigest,
+      _dontDeliver,
+      _deliverMode,
+      _msgToReplace,
+      _bodyType,
+      _body,
+      _parentWindow,
+      _progress,
+      listener
+    ) {
+      this.listener = listener;
+      return Promise.resolve();
+    },
+
+    QueryInterface: ChromeUtils.generateQI(["nsIObserver", "nsIMsgSend"]),
+  };
+
+  Services.obs.addObserver(fakeSend, "mail-set-sender");
+  registerCleanupFunction(() => {
+    Services.obs.removeObserver(fakeSend, "mail-set-sender");
+  });
+
+  const identity = getSmtpIdentity(
+    "sender@example.invalid",
+    getBasicSmtpServer()
+  );
+  const fields = Cc[
+    "@mozilla.org/messengercompose/composefields;1"
+  ].createInstance(Ci.nsIMsgCompFields);
+  fields.to = "recipient@example.invalid";
+  fields.subject = "Test OnStopCopy after compose GC";
+  fields.body = "Body";
+
+  const params = Cc[
+    "@mozilla.org/messengercompose/composeparams;1"
+  ].createInstance(Ci.nsIMsgComposeParams);
+  params.composeFields = fields;
+
+  let msgCompose = MailServices.compose.initCompose(params);
+  const progress = Cc["@mozilla.org/messenger/progress;1"].createInstance(
+    Ci.nsIMsgProgress
+  );
+
+  const progressStopped = Promise.withResolvers();
+  const progressListener = {
+    onStateChange(_webProgress, _request, stateFlags, status) {
+      if (stateFlags & Ci.nsIWebProgressListener.STATE_STOP) {
+        progressStopped.resolve(status);
+      }
+    },
+    onProgressChange() {},
+    onLocationChange() {},
+    onStatusChange() {},
+    onSecurityChange() {},
+    onContentBlockingEvent() {},
+
+    QueryInterface: ChromeUtils.generateQI([
+      "nsIWebProgressListener",
+      "nsISupportsWeakReference",
+    ]),
+  };
+  progress.registerListener(progressListener);
+
+  const sendPromise = msgCompose.sendMsg(
+    Ci.nsIMsgSend.nsMsgDeliverNow,
+    identity,
+    "",
+    progress
+  );
+  Assert.ok(fakeSend.listener, "sendMsg should create a send listener");
+  await sendPromise;
+  await new Promise(resolve => do_timeout(0, resolve));
+
+  const copyListener = fakeSend.listener.QueryInterface(
+    Ci.nsIMsgCopyServiceListener
+  );
+
+  // MessageSend defers onStopCopy() until after the send promise resolves.
+  // Force the garbage collection that may drop the weak compose reference in
+  // that gap.
+  msgCompose = null;
+  Cu.forceGC();
+  Cu.forceCC();
+  Cu.forceGC();
+
+  copyListener.onStopCopy(Cr.NS_OK);
+
+  const stopStatus = await Promise.race([
+    progressStopped.promise,
+    new Promise((_, reject) =>
+      do_timeout(1000, () =>
+        reject(new Error("Timed out waiting for progress to stop"))
+      )
+    ),
+  ]);
+
+  Assert.equal(
+    stopStatus,
+    Cr.NS_OK,
+    "onStopCopy should close the progress dialog after compose GC"
+  );
+});
